INSERT OR IGNORE INTO settings (id, data, updated_at) VALUES ('site', '{"brand_name":"PhotoFram","tagline":"Your memories, beautifully framed","logo":"","colors":{"primary":"#2346d8","primary_hover":"#1b37b0","tint":"#eef2ff","background":"#ffffff"},"whatsapp":"","phone_display":"","instagram":"","facebook_url":"","youtube_url":"","google_reviews_url":"","address":{"line1":"","line2":"","city":"","state":"","pin":""},"shipping":{"flat_fee":50,"free_above":299,"processing_days":"1-2 business days","occasion_lead_days":15},"announcement":"Free shipping on orders above ₹299","hours":"Mon – Sat: 9:30 AM – 8:30 PM · Sunday closed"}', '2026-11-24T00:00:00.000Z');
INSERT OR IGNORE INTO items (id, kind, position, hidden, data, created_at, updated_at) VALUES ('seed-faq-1', 'faq', 0, 0, '{"q":"How do I order a personalized photo frame?","a":"Choose a frame template, upload your photos into each slot, adjust them until the live preview looks right, pick a size and frame finish, and send us the order on WhatsApp. We confirm the design and payment there."}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT OR IGNORE INTO items (id, kind, position, hidden, data, created_at, updated_at) VALUES ('seed-faq-2', 'faq', 1, 0, '{"q":"When should I order for a special occasion?","a":"Please order at least 15 working days before the occasion so there is time to resolve any delays or issues."}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT OR IGNORE INTO items (id, kind, position, hidden, data, created_at, updated_at) VALUES ('seed-faq-3', 'faq', 2, 0, '{"q":"Is there a shipping fee?","a":"A flat ₹50 shipping fee applies to orders up to ₹299. Orders above ₹299 ship free."}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT OR IGNORE INTO items (id, kind, position, hidden, data, created_at, updated_at) VALUES ('seed-faq-4', 'faq', 3, 0, '{"q":"How long does processing take?","a":"Most orders are processed within 1–2 business days after the design and payment are confirmed."}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT OR IGNORE INTO items (id, kind, position, hidden, data, created_at, updated_at) VALUES ('seed-faq-5', 'faq', 4, 0, '{"q":"Will the printed frame look exactly like the preview?","a":"The live preview shows your exact layout, crop and text. Printed colours can differ slightly (about 10–20%) from what you see on a screen because of screen brightness and print materials."}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT OR IGNORE INTO items (id, kind, position, hidden, data, created_at, updated_at) VALUES ('seed-faq-6', 'faq', 5, 0, '{"q":"Do you edit or retouch my photos?","a":"No — we print the photos exactly as you upload and crop them. If you need colour correction or retouching, contact us on WhatsApp before ordering; extra charges apply."}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT OR IGNORE INTO items (id, kind, position, hidden, data, created_at, updated_at) VALUES ('seed-faq-7', 'faq', 6, 0, '{"q":"Can I place a bulk or corporate order?","a":"Yes, we offer special discounts on bulk orders for weddings, corporate gifting and events. Message us on WhatsApp with your requirement."}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
